"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import * as XLSX from "xlsx";
import { Search, Package, Upload, Download, Plus, X, Lock } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { fetchCurrentEmployee, fetchStores, type Employee, type Store } from "@/lib/journeys/queries";
import {
  fetchProductsWithStock,
  adjustInventoryPosition,
  previewCommittedShortfall,
  hasPermission,
  upsertProduct,
  type CommittedShortfallPreviewItem,
  type Product,
  type ProductWithStock,
} from "@/lib/inventory/queries";
import { fetchProductCategories } from "@/lib/financing/queries";
import Modal from "@/components/Modal";
import type { ProductCategory } from "@/lib/financing/types";
import {
  fetchRestockCandidates,
  fetchRestockGenerationMode,
} from "@/lib/transfers/queries";

type ImportMapping = {
  SKU: number | null;
  "Item Name": number | null;
  Brand: number | null;
  Cost: number | null;
  Price: number | null;
  "Sale Price": number | null;
};

const REQUIRED_FIELDS = ["SKU", "Item Name"] as const;
const ALL_FIELDS = [
  "SKU",
  "Item Name",
  "Brand",
  "Cost",
  "Price",
  "Sale Price",
] as const;

function coerceMoney(value: unknown): number | null {
  if (value === undefined || value === null) return null;
  const str = String(value).trim();
  if (str === "") return null;
  const cleaned = str.replace(/[$,\s]/g, "");
  const n = parseFloat(cleaned);
  if (Number.isNaN(n)) return null;
  return n;
}

export default function InventoryPage() {
  const router = useRouter();
  const [employee, setEmployee] = useState<Employee | null>(null);

  const [pageError, setPageError] = useState<string | null>(null);
  const [stores, setStores] = useState<Store[]>([]);
  const [currentStoreId, setCurrentStoreId] = useState<string>("");
  const [products, setProducts] = useState<ProductWithStock[]>([]);
  const [loading, setLoading] = useState(true);
  const [canAdjustInventory, setCanAdjustInventory] = useState(false);
  const [canViewPhysical, setCanViewPhysical] = useState(false);
  const [canEditProducts, setCanEditProducts] = useState(false);
  const [canManageParLevels, setCanManageParLevels] = useState(false);
  const [restockBadgeCount, setRestockBadgeCount] = useState(0);
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState<"ats" | "physical">("ats");

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [shortfall, setShortfall] = useState<{
    productId: string;
    qty: number;
    items: CommittedShortfallPreviewItem[];
    unattributedUnits: number;
    canOverride: boolean;
  } | null>(null);
  const [overrideReason, setOverrideReason] = useState("");
  const [shortfallSaving, setShortfallSaving] = useState(false);
  const [stockInputsVersion, setStockInputsVersion] = useState(0);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkCategories, setBulkCategories] = useState<ProductCategory[]>([]);
  const [bulkCategoryId, setBulkCategoryId] = useState<string>("");
  const [bulkBusy, setBulkBusy] = useState(false);

  const [uploadStep, setUploadStep] = useState<"idle" | "mapping" | "preview" | "summary">("idle");
  const [rawRows, setRawRows] = useState<unknown[][]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ImportMapping>({
    SKU: null,
    "Item Name": null,
    Brand: null,
    Cost: null,
    Price: null,
    "Sale Price": null,
  });
  const [importSummary, setImportSummary] = useState<{
    created: number;
    updated: number;
    skipped: { row: number; reason: string }[];
  } | null>(null);

  const canViewAll =
    employee?.role === "owner" ||
    employee?.role === "admin" ||
    employee?.role === "manager";

  const companyId = useMemo(() => {
    if (!employee?.home_store_id) return null;
    return stores.find((s) => s.id === employee.home_store_id)?.company_id ?? null;
  }, [employee, stores]);

  // Restock attention badge on the Transfers link — manual mode only, scoped
  // the same way as the Restock tab (manager: home store; owner/admin: all).
  useEffect(() => {
    if (!canViewAll || !companyId || !employee) return;
    fetchRestockGenerationMode(companyId).then(async (mode) => {
      if (mode !== "manual") return;
      setRestockBadgeCount(
        (await fetchRestockCandidates(stores, employee)).length
      );
    });
  }, [canViewAll, companyId, employee, stores]);

  useEffect(() => {
    const supabase = createClient();
    supabase.auth.getSession().then(async ({ data: { session } }) => {
      if (!session?.user) {
        router.push("/login");
        return;
      }
      const [e, s] = await Promise.all([fetchCurrentEmployee(), fetchStores()]);
      setEmployee(e);
      setStores(s);
      const homeStore = s.find((st) => st.id === e?.home_store_id);
      const defaultLocation = homeStore?.assigned_warehouse_id ?? e?.home_store_id;
      const active =
        session.user.user_metadata?.active_store_id ?? defaultLocation ?? s[0]?.id ?? "";
      setCurrentStoreId(active);

      const company = s.find((st) => st.id === e?.home_store_id)?.company_id;
      let canAdjust = e?.role === "owner" || e?.role === "admin";
      let canViewPhysical = canAdjust;
      let canEdit = canAdjust;
      let canPar = canAdjust;
      if (e?.role === "manager" && company) {
        const { data } = await (supabase as any)
          .from("companies")
          .select(
            "managers_can_adjust_inventory, managers_can_view_physical_inventory, managers_can_edit_products, managers_can_manage_par_levels"
          )
          .eq("id", company)
          .single();
        canAdjust = data?.managers_can_adjust_inventory === true;
        canViewPhysical = data?.managers_can_view_physical_inventory === true;
        canEdit = data?.managers_can_edit_products === true;
        canPar = data?.managers_can_manage_par_levels === true;
      }
      setCanAdjustInventory(canAdjust);
      setCanViewPhysical(canViewPhysical);
      setCanEditProducts(canEdit);
      setCanManageParLevels(canPar);

      loadProducts(active);
    });
  }, [router]);

  async function loadProducts(storeId: string) {
    setLoading(true);
    const data = await fetchProductsWithStock(storeId);
    setProducts(data);
    setLoading(false);
  }

  const filtered = useMemo(() => {
    const term = search.trim().toLowerCase();
    const list = term
      ? products.filter((p) => p.search_text?.toLowerCase().includes(term))
      : [...products];
    // In-stock first (positive qty on the selected basis), alphabetical within
    // each group; zero/null quantities sort after.
    const qty = (p: ProductWithStock) =>
      (sortBy === "physical" ? p.physical : p.ats) ?? 0;
    return list.sort(
      (a, b) =>
        Number(qty(b) > 0) - Number(qty(a) > 0) ||
        a.item_name.localeCompare(b.item_name)
    );
  }, [products, search, sortBy]);

  useEffect(() => {
    if (canEditProducts && companyId) {
      fetchProductCategories(companyId).then(setBulkCategories);
    }
  }, [canEditProducts, companyId]);

  const visibleIds = filtered.map((p) => p.id);
  const allVisibleSelected =
    visibleIds.length > 0 && visibleIds.every((id) => selectedIds.has(id));

  function toggleSelect(id: string) {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  function toggleSelectAll() {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allVisibleSelected) visibleIds.forEach((id) => next.delete(id));
      else visibleIds.forEach((id) => next.add(id));
      return next;
    });
  }

  async function applyBulkCategory() {
    if (selectedIds.size === 0) return;
    setBulkBusy(true);
    try {
      setPageError(null);
      const supabase = createClient();
      const { error } = await supabase
        .from("products")
        .update({ category_id: bulkCategoryId || null })
        .in("id", Array.from(selectedIds));
      if (error) throw new Error(error.message);
      setProducts((prev) =>
        prev.map((p) =>
          selectedIds.has(p.id) ? { ...p, category_id: bulkCategoryId || null } : p
        )
      );
      setSelectedIds(new Set());
    } catch (e: any) {
      setPageError(e.message);
    } finally {
      setBulkBusy(false);
    }
  }

  function onFileSelected(file: File) {
    const reader = new FileReader();
    reader.onload = (e) => {
      const data = e.target?.result;
      if (!data) return;
      const workbook = XLSX.read(data, { type: "array" });
      const sheetName = workbook.SheetNames[0];
      const sheet = workbook.Sheets[sheetName];
      const rows = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as unknown[][];
      if (rows.length < 1) return;

      const h = rows[0].map((x) => (x === undefined ? "" : String(x).trim()));
      setHeaders(h);
      setRawRows(rows.slice(1));

      const guess: Partial<ImportMapping> = {};
      h.forEach((header, idx) => {
        const lower = header.toLowerCase();
        if (!guess.SKU && /\bsku\b/i.test(lower)) guess.SKU = idx;
        if (!guess["Item Name"] && /\b(item\s?name|product\s?name|name)\b/i.test(lower)) guess["Item Name"] = idx;
        if (!guess.Brand && /\bbrand\b/i.test(lower)) guess.Brand = idx;
        if (!guess.Cost && /\bcost\b/i.test(lower)) guess.Cost = idx;
        if (!guess.Price && /\bprice\b/i.test(lower) && !/sale/i.test(lower)) guess.Price = idx;
        if (!guess["Sale Price"] && /\b(sale\s?price|sale)\b/i.test(lower)) guess["Sale Price"] = idx;
      });

      setMapping((m) => ({ ...m, ...guess }));
      setUploadStep("mapping");
    };
    reader.readAsArrayBuffer(file);
  }

  function downloadTemplate() {
    const headers = ["SKU", "Item Name", "Cost", "Price", "Sales Price", "Brand"];
    const ws = XLSX.utils.aoa_to_sheet([headers]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Inventory Template");
    const data = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    const blob = new Blob([data], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "pillowtop-inventory-template.xlsx";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  function canPreview() {
    return REQUIRED_FIELDS.every((f) => mapping[f] !== null);
  }

  function mappedRows() {
    const out: Record<string, unknown>[] = [];
    for (const row of rawRows) {
      const obj: Record<string, unknown> = {};
      for (const field of ALL_FIELDS) {
        const idx = mapping[field];
        obj[field] = idx !== null ? row[idx] : undefined;
      }
      out.push(obj);
    }
    return out;
  }

  async function runImport() {
    if (!companyId) return;
    const rows = mappedRows();
    const records: Partial<Product & { company_id: string }>[] = [];
    const skipped: { row: number; reason: string }[] = [];

    rows.forEach((row, idx) => {
      const sku = (row.SKU ?? "").toString().trim();
      const itemName = (row["Item Name"] ?? "").toString().trim();
      if (!sku || !itemName) {
        skipped.push({ row: idx + 2, reason: "Missing SKU or Item Name" });
        return;
      }

      const brand = (row.Brand ?? "").toString().trim() || null;
      const cost = coerceMoney(row.Cost);
      const price = coerceMoney(row.Price);
      const salePrice = coerceMoney(row["Sale Price"]);

      if (row.Cost !== undefined && row.Cost !== null && row.Cost.toString().trim() !== "" && cost === null) {
        setPageError(null);
        skipped.push({ row: idx + 2, reason: "Cost is not a valid number" });
        return;
      }
      if (row.Price !== undefined && row.Price !== null && row.Price.toString().trim() !== "" && price === null) {
        skipped.push({ row: idx + 2, reason: "Price is not a valid number" });
        return;
      }
      if (row["Sale Price"] !== undefined && row["Sale Price"] !== null && row["Sale Price"].toString().trim() !== "" && salePrice === null) {
        skipped.push({ row: idx + 2, reason: "Sale Price is not a valid number" });
        return;
      }

      records.push({
        company_id: companyId,
        sku,
        item_name: itemName,
        brand,
        cost,
        price,
        sale_price: salePrice,
      });
    });

    const supabase = createClient();
    const { error } = await supabase
      .from("products")
      .upsert(records, { onConflict: "company_id,sku", ignoreDuplicates: false });

    if (error) {
      setPageError(error.message);
      return;
    }

    const created = records.length;
    setImportSummary({
      created,
      updated: 0,
      skipped,
    });
    setUploadStep("summary");
    loadProducts(currentStoreId);
  }

  // defaultValue inputs never re-read props: bumping the version remounts
  // them so a cancelled or failed edit can never leave a typed number on
  // screen, and a re-fetch shows the real stock after a save.
  function resetStockInputs() {
    setStockInputsVersion((v) => v + 1);
    loadProducts(currentStoreId);
  }

  async function saveStock(productId: string, value: string) {
    const qty = Math.max(0, Math.floor(Number(value) || 0));
    try {
      setPageError(null);
      await adjustInventoryPosition(productId, currentStoreId, qty);
      resetStockInputs();
    } catch (e: any) {
      if (typeof e?.message === "string" && e.message.startsWith("COMMITTED_SHORTFALL:")) {
        const [preview, canOverride] = await Promise.all([
          previewCommittedShortfall(productId, currentStoreId, qty),
          hasPermission("inventory.reduce_below_committed"),
        ]);
        setOverrideReason("");
        setShortfall({
          productId,
          qty,
          items: preview.items,
          unattributedUnits: preview.unattributed_units,
          canOverride,
        });
        return;
      }
      setPageError(
        e?.code === "40P01"
          ? "Something else was updating this item. Please try again."
          : e?.message ?? "Failed to update stock"
      );
      resetStockInputs();
    }
  }

  async function proceedWithShortfall() {
    if (!shortfall) return;
    setShortfallSaving(true);
    try {
      setPageError(null);
      await adjustInventoryPosition(shortfall.productId, currentStoreId, shortfall.qty, {
        overrideBelowCommitted: true,
        overrideReason: overrideReason.trim(),
      });
      setShortfall(null);
      resetStockInputs();
    } catch (e: any) {
      setPageError(
        e?.code === "40P01"
          ? "Something else was updating this item. Please try again."
          : e?.message ?? "Failed to update stock"
      );
      resetStockInputs();
    } finally {
      setShortfallSaving(false);
    }
  }

  function closeShortfall() {
    setShortfall(null);
    resetStockInputs();
  }

  async function saveProduct(product: Product | null) {
    setPageError(null);
    if (!companyId || !product) return;
    await upsertProduct({ ...product, company_id: companyId });
    setEditingProduct(null);
    loadProducts(currentStoreId);
  }

  return (
    <main className="min-h-screen bg-slate-50 p-6">
      {pageError && (
        <p key="page-error" role="alert" className="mb-3 rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{pageError}</p>
      )}
      <header className="mb-4 flex flex-wrap items-center justify-between gap-4">
        <h1 className="text-2xl font-semibold text-slate-900">Inventory</h1>
        <div className="flex items-center gap-2">
          {canViewAll &&
            (canManageParLevels ? (
              <Link
                href="/inventory/par-levels"
                className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
              >
                Par Levels
              </Link>
            ) : (
              <button
                type="button"
                onClick={() =>
                  setPageError(
                    "Par Levels is restricted. An owner or admin needs to enable manager access in Company Settings."
                  )
                }
                className="inline-flex cursor-not-allowed items-center gap-2 rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 opacity-75"
              >
                <Lock className="h-4 w-4" /> Par Levels
              </button>
            ))}
          <Link
            href="/purchase-orders"
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Purchase Orders
          </Link>
          <Link
            href="/transfers"
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Transfers
            {restockBadgeCount > 0 && (
              <span className="ml-1.5 inline-flex h-5 min-w-5 items-center justify-center rounded-full bg-amber-500 px-1.5 text-xs font-semibold text-white">
                {restockBadgeCount}
              </span>
            )}
          </Link>
          <Link
            href="/counts"
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Counts
          </Link>
          <Link
            href="/units"
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Units
          </Link>
          <Link
            href="/board"
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Back to Board
          </Link>
        </div>
      </header>

      <div className="mb-4 flex flex-wrap items-center gap-3">
        <div className="relative">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search products"
            className="w-64 rounded-md border border-slate-300 py-2 pl-9 pr-3 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
          />
        </div>

        <div className="flex items-center gap-1 text-sm text-slate-600">
          <span className="mr-1">Sort by:</span>
          {(["ats", "physical"] as const).map((opt) => (
            <button
              key={opt}
              type="button"
              onClick={() => setSortBy(opt)}
              className={`rounded-md px-2.5 py-1.5 text-sm font-medium ${
                sortBy === opt
                  ? "bg-brand-600 text-white"
                  : "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50"
              }`}
            >
              {opt === "ats" ? "ATS" : "Physical"}
            </button>
          ))}
        </div>

        {canViewAll && (
          <select
            value={currentStoreId}
            onChange={(e) => {
              setCurrentStoreId(e.target.value);
              loadProducts(e.target.value);
            }}
            className="rounded-md border border-slate-300 bg-white px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
          >
            {stores.map((s) => (
              <option key={s.id} value={s.id}>
                {s.name}
              </option>
            ))}
          </select>
        )}

        {canEditProducts && (
          <>
            <label className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-brand-600 px-3 py-2 text-sm font-medium text-white hover:bg-brand-700">
              <Upload className="h-4 w-4" /> Upload file
              <input
                type="file"
                accept=".csv,.xlsx"
                className="hidden"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) onFileSelected(file);
                  e.target.value = "";
                }}
              />
            </label>
            <button
              onClick={downloadTemplate}
              className="inline-flex items-center gap-2 rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
            >
              <Download className="h-4 w-4" /> Template
            </button>
            <button
              onClick={() =>
                setEditingProduct({
                  id: "",
                  company_id: companyId ?? "",
                  sku: "",
                  item_name: "",
                  category_id: null,
                  sleep_trial_eligible: null,
                  brand: null,
                  cost: null,
                  price: null,
                  sale_price: null,
                  search_text: "",
                  created_at: "",
                  updated_at: "",
                })
              }
              className="inline-flex items-center gap-2 rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
            >
              <Plus className="h-4 w-4" /> Add product
            </button>
          </>
        )}
      </div>

      {canEditProducts && selectedIds.size > 0 && (
        <div className="flex items-center gap-3 rounded-lg border border-slate-200 bg-white px-4 py-2 text-sm">
          <span className="font-medium text-slate-700">{selectedIds.size} selected</span>
          <select
            value={bulkCategoryId}
            onChange={(e) => setBulkCategoryId(e.target.value)}
            className="rounded-md border border-slate-300 px-2 py-1 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
          >
            <option value="">Uncategorized</option>
            {bulkCategories.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
          <button
            onClick={applyBulkCategory}
            disabled={bulkBusy}
            className="rounded-md bg-brand-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-brand-700 disabled:opacity-50"
          >
            {bulkBusy ? "Applying…" : "Set category"}
          </button>
          <button
            onClick={() => setSelectedIds(new Set())}
            className="text-sm text-slate-500 hover:text-slate-700"
          >
            Clear
          </button>
        </div>
      )}

      {loading ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-slate-200 bg-white">
          <table className="w-full text-sm">
            <thead className="border-b border-slate-200 bg-slate-50 text-left">
              <tr>
                {canEditProducts && (
                  <th className="w-8 px-4 py-2">
                    <input
                      type="checkbox"
                      checked={allVisibleSelected}
                      onChange={toggleSelectAll}
                      className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500"
                    />
                  </th>
                )}
                <th className="px-4 py-2 font-medium text-slate-700">SKU</th>
                <th className="px-4 py-2 font-medium text-slate-700">Item Name</th>
                <th className="px-4 py-2 font-medium text-slate-700">Brand</th>
                <th className="px-4 py-2 font-medium text-slate-700">Cost</th>
                <th className="px-4 py-2 font-medium text-slate-700">Price</th>
                <th className="px-4 py-2 font-medium text-slate-700">Sale Price</th>
                {canViewPhysical && (
                  <th className="px-4 py-2 font-medium text-slate-700">Physical</th>
                )}
                <th className="px-4 py-2 font-medium text-slate-700">ATS</th>
                <th className="px-4 py-2 font-medium text-slate-700"></th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((p) => (
                <tr key={p.id} className="border-b border-slate-100 hover:bg-slate-50">
                  {canEditProducts && (
                    <td className="px-4 py-2">
                      <input
                        type="checkbox"
                        checked={selectedIds.has(p.id)}
                        onChange={() => toggleSelect(p.id)}
                        className="h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-500"
                      />
                    </td>
                  )}
                  <td className="px-4 py-2">{p.sku}</td>
                  <td className="px-4 py-2 font-medium text-slate-900">{p.item_name}</td>
                  <td className="px-4 py-2">{p.brand ?? "—"}</td>
                  <td className="px-4 py-2">{p.cost?.toFixed(2) ?? "—"}</td>
                  <td className="px-4 py-2">{p.price?.toFixed(2) ?? "—"}</td>
                  <td className="px-4 py-2">{p.sale_price?.toFixed(2) ?? "—"}</td>
                  {canViewPhysical && (
                    <td className="px-4 py-2">
                      {canAdjustInventory ? (
                        <input
                          type="number"
                          min={0}
                          key={`${p.id}:${p.physical ?? 0}:${stockInputsVersion}`}
                          defaultValue={p.physical ?? 0}
                          onBlur={(e) => saveStock(p.id, e.target.value)}
                          className="w-20 rounded-md border border-slate-300 px-2 py-1 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
                        />
                      ) : (
                        <span className="text-slate-700">{p.physical ?? "—"}</span>
                      )}
                    </td>
                  )}
                  <td className="px-4 py-2 text-slate-700">{p.ats ?? 0}</td>
                  <td className="px-4 py-2">
                    {canEditProducts && (
                      <button
                        onClick={() => setEditingProduct(p)}
                        className="text-sm text-brand-600 hover:text-brand-700"
                      >
                        Edit
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {shortfall && (
        <Modal onClose={closeShortfall} saving={shortfallSaving}>
          <div className="w-full max-w-lg rounded-lg border border-slate-200 bg-white p-6 shadow-lg">
                  {pageError && (
                    <p key="modal-error" role="alert" className="mb-3 rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{pageError}</p>
                  )}
            <h2 className="mb-1 text-lg font-semibold text-slate-900">
              Stock below committed
            </h2>
            <p className="mb-4 text-sm text-slate-600">
              Setting on-hand to {shortfall.qty} leaves reserved units uncovered.
              {shortfall.items.some((it) => it.will_release && !it.already_waiting)
                ? " Journeys marked below move back to Waiting for Inventory and a follow-up task will be created for each."
                : " These journeys hold reservations for this item."}
            </p>
            <ul className="mb-4 max-h-64 space-y-2 overflow-y-auto">
              {shortfall.items.map((it) => (
                <li
                  key={it.requirement_id}
                  className="rounded-md border border-slate-200 px-3 py-2 text-sm"
                >
                  <div className="flex items-center justify-between gap-2">
                    <span className="font-medium text-slate-900">
                      {it.customer_name}
                    </span>
                    <span className="text-slate-500">{it.current_state}</span>
                  </div>
                  <div className="text-xs text-slate-500">
                    {it.quantity_reserved} reserved
                    {it.delivery_date
                      ? ` · delivery ${new Date(it.delivery_date + "T00:00:00").toLocaleDateString()}`
                      : ""}
                    {it.will_release && it.already_waiting
                      ? " · already waiting, no change"
                      : it.will_release
                        ? " · will move back to Waiting for Inventory"
                        : ""}
                  </div>
                </li>
              ))}
              {shortfall.items.length === 0 && (
                <li className="text-sm text-slate-500">
                  No open journeys hold reservations for this item.
                </li>
              )}
            </ul>
            {shortfall.unattributedUnits > 0 && (
              <p className="mb-4 text-sm text-slate-600">
                {shortfall.unattributedUnits} reserved unit(s) are not tied to
                any open journey and will be cleared.
              </p>
            )}
            {shortfall.canOverride ? (
              <>
                <label className="mb-1 block text-xs font-medium text-slate-600">
                  Reason for reducing below committed
                </label>
                <input
                  type="text"
                  value={overrideReason}
                  onChange={(e) => setOverrideReason(e.target.value)}
                  placeholder="e.g. 2 units damaged in warehouse"
                  className="mb-4 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
                />
                <div className="flex justify-end gap-2">
                  <button
                    onClick={closeShortfall}
                    disabled={shortfallSaving}
                    className="rounded-md border border-slate-300 px-3 py-2 text-sm text-slate-700 hover:bg-slate-50 disabled:opacity-50"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={proceedWithShortfall}
                    disabled={shortfallSaving || overrideReason.trim() === ""}
                    className="rounded-md bg-red-600 px-3 py-2 text-sm font-medium text-white hover:bg-red-700 disabled:opacity-50"
                  >
                    {shortfallSaving ? "Saving…" : "Proceed anyway"}
                  </button>
                </div>
              </>
            ) : (
              <div className="flex items-center justify-between gap-4">
                <p className="text-sm text-slate-600">
                  Ask a manager to make this change
                </p>
                <button
                  onClick={closeShortfall}
                  className="rounded-md border border-slate-300 px-3 py-2 text-sm text-slate-700 hover:bg-slate-50"
                >
                  Cancel
                </button>
              </div>
            )}
          </div>
        </Modal>
      )}

      {uploadStep !== "idle" && (
        <Modal
          onClose={() => setUploadStep("idle")}
          dirty={uploadStep === "mapping" || uploadStep === "preview"}
        >
          <div className="w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-lg border border-slate-200 bg-white p-6 shadow-lg">
                  {pageError && (
                    <p key="modal-error" role="alert" className="mb-3 rounded-md border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{pageError}</p>
                  )}
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-lg font-semibold text-slate-900">
                {uploadStep === "mapping" && "Map columns"}
                {uploadStep === "preview" && "Preview import"}
                {uploadStep === "summary" && "Import summary"}
              </h2>
              <button
                onClick={() => setUploadStep("idle")}
                className="rounded-md p-1 text-slate-500 hover:bg-slate-100"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {uploadStep === "mapping" && (
              <div className="space-y-4">
                <p className="text-sm text-slate-600">
                  Match each required field to a column from the uploaded file. {rawRows.length} rows found.
                </p>
                <div className="grid grid-cols-2 gap-4">
                  {ALL_FIELDS.map((field) => (
                    <div key={field}>
                      <label className="block text-sm font-medium text-slate-700">
                        {field} {REQUIRED_FIELDS.includes(field as any) && <span className="text-red-500">*</span>}
                      </label>
                      <select
                        value={mapping[field] ?? ""}
                        onChange={(e) =>
                          setMapping((m) => ({
                            ...m,
                            [field]: e.target.value === "" ? null : Number(e.target.value),
                          }))
                        }
                        className="mt-1 w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
                      >
                        <option value="">—</option>
                        {headers.map((h, idx) => (
                          <option key={idx} value={idx}>
                            {h}
                          </option>
                        ))}
                      </select>
                    </div>
                  ))}
                </div>
                <button
                  onClick={() => canPreview() && setUploadStep("preview")}
                  disabled={!canPreview()}
                  className="rounded-md bg-brand-600 px-4 py-2 text-sm font-medium text-white hover:bg-brand-700 disabled:opacity-50"
                >
                  Preview
                </button>
              </div>
            )}

            {uploadStep === "preview" && (
              <div className="space-y-4">
                <p className="text-sm text-slate-600">First rows after mapping:</p>
                <div className="overflow-x-auto rounded-md border border-slate-200">
                  <table className="w-full text-sm">
                    <thead className="bg-slate-50">
                      <tr>
                        {ALL_FIELDS.map((f) => (
                          <th key={f} className="px-3 py-2 text-left font-medium text-slate-700">
                            {f}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {mappedRows().slice(0, 10).map((row, idx) => (
                        <tr key={idx} className="border-b border-slate-100">
                          {ALL_FIELDS.map((f) => (
                            <td key={f} className="px-3 py-2">{String(row[f] ?? "—")}</td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={runImport}
                    className="rounded-md bg-brand-600 px-4 py-2 text-sm font-medium text-white hover:bg-brand-700"
                  >
                    Import {rawRows.length} rows
                  </button>
                  <button
                    onClick={() => setUploadStep("mapping")}
                    className="rounded-md border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
                  >
                    Back
                  </button>
                </div>
              </div>
            )}

            {uploadStep === "summary" && importSummary && (
              <div className="space-y-4">
                <p className="text-sm text-slate-600">
                  Imported <strong>{importSummary.created}</strong> rows.
                </p>
                {importSummary.skipped.length > 0 && (
                  <div>
                    <p className="text-sm font-medium text-amber-700">
                      {importSummary.skipped.length} rows skipped
                    </p>
                    <ul className="mt-1 max-h-40 overflow-y-auto rounded-md border border-slate-200 bg-slate-50 p-2 text-xs text-slate-600">
                      {importSummary.skipped.map((s, idx) => (
                        <li key={idx}>Row {s.row}: {s.reason}</li>
                      ))}
                    </ul>
                  </div>
                )}
                <button
                  onClick={() => setUploadStep("idle")}
                  className="rounded-md bg-brand-600 px-4 py-2 text-sm font-medium text-white hover:bg-brand-700"
                >
                  Done
                </button>
              </div>
            )}
          </div>
        </Modal>
      )}

      {editingProduct && (
        <ProductModal
          product={editingProduct}
          companyId={companyId}
          onClose={() => setEditingProduct(null)}
          onSave={(p) => {
            setEditingProduct(p);
            saveProduct(p);
          }}
        />
      )}
    </main>
  );
}

function ProductModal({
  product,
  companyId,
  onClose,
  onSave,
}: {
  product: Product;
  companyId: string | null;
  onClose: () => void;
  onSave: (p: Product) => void;
}) {
  const [p, setP] = useState<Product>(product);
  const [categories, setCategories] = useState<ProductCategory[]>([]);

  useEffect(() => {
    if (companyId) {
      fetchProductCategories(companyId).then(setCategories);
    }
  }, [companyId]);

  return (
    <Modal
      onClose={onClose}
      dirty={JSON.stringify(p) !== JSON.stringify(product)}
    >
      <div className="max-h-[90vh] w-full max-w-md overflow-y-auto rounded-lg border border-slate-200 bg-white p-6 shadow-lg">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-slate-900">
            {product.id ? "Edit product" : "Add product"}
          </h2>
          <button onClick={onClose} className="rounded-md p-1 text-slate-500 hover:bg-slate-100">
            <X className="h-5 w-5" />
          </button>
        </div>
        <div className="space-y-3">
          <div>
            <label className="block text-sm font-medium text-slate-700">SKU *</label>
            <input
              value={p.sku}
              onChange={(e) => setP((x) => ({ ...x, sku: e.target.value }))}
              className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700">Item Name *</label>
            <input
              value={p.item_name}
              onChange={(e) => setP((x) => ({ ...x, item_name: e.target.value }))}
              className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700">Brand</label>
            <input
              value={p.brand ?? ""}
              onChange={(e) => setP((x) => ({ ...x, brand: e.target.value || null }))}
              className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700">Category</label>
            <select
              value={p.category_id ?? ""}
              onChange={(e) =>
                setP((x) => ({ ...x, category_id: e.target.value || null }))
              }
              className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
            >
              <option value="">Uncategorized</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700">Sleep trial</label>
            <select
              value={
                p.sleep_trial_eligible === null || p.sleep_trial_eligible === undefined
                  ? "inherit"
                  : p.sleep_trial_eligible
                    ? "yes"
                    : "no"
              }
              onChange={(e) =>
                setP((x) => ({
                  ...x,
                  sleep_trial_eligible:
                    e.target.value === "inherit" ? null : e.target.value === "yes",
                }))
              }
              className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
            >
              <option value="inherit">Inherit from category</option>
              <option value="yes">Eligible</option>
              <option value="no">Not eligible</option>
            </select>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <div>
              <label className="block text-sm font-medium text-slate-700">Cost</label>
              <input
                type="number"
                value={p.cost ?? ""}
                onChange={(e) =>
                  setP((x) => ({ ...x, cost: e.target.value === "" ? null : Number(e.target.value) }))
                }
                className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700">Price</label>
              <input
                type="number"
                value={p.price ?? ""}
                onChange={(e) =>
                  setP((x) => ({ ...x, price: e.target.value === "" ? null : Number(e.target.value) }))
                }
                className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700">Sale Price</label>
              <input
                type="number"
                value={p.sale_price ?? ""}
                onChange={(e) =>
                  setP((x) => ({ ...x, sale_price: e.target.value === "" ? null : Number(e.target.value) }))
                }
                className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500"
              />
            </div>
          </div>
        </div>
        <div className="mt-4 flex gap-2">
          <button
            onClick={() => onSave(p)}
            disabled={!p.sku || !p.item_name}
            className="flex-1 rounded-md bg-brand-600 px-3 py-2 text-sm font-medium text-white hover:bg-brand-700 disabled:opacity-50"
          >
            Save
          </button>
          <button
            onClick={onClose}
            className="flex-1 rounded-md border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50"
          >
            Cancel
          </button>
        </div>
      </div>
    </Modal>
  );
}
